begin;
set local timezone='America/Bahia';
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1190000-0000-4000-8000-000000000001','authenticated','authenticated','field-a@example.test','',now(),'{}','{"name":"Field QA A","company_name":"Field QA A"}',now(),now()),
('b1190000-0000-4000-8000-000000000002','authenticated','authenticated','field-b@example.test','',now(),'{}','{"name":"Field QA B","company_name":"Field QA B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b1190000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('field.company',private.current_company_id(),true);
insert into public.customers(id,company_id,name,document,phone,email,address,tags,notes) values('i-customer',private.current_company_id(),'Cliente QA','', '81900000000','qa@example.test','{"street":"Rua QA","number":"1","city":"Recife","state":"PE"}','{}','QA');
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('i-material',private.current_company_id(),'Material de campo QA','unidade',2,5,true,10,0);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('i-order',private.current_company_id(),'i-customer','Cliente QA','PED-119','producao',100,0,'pendente',0,now()+interval '2 days','QA');
insert into public.order_items(id,order_id,product_name,quantity,unit_price,total_price,details) values('i-item','i-order','Serviço QA',1,100,100,'{}');
create function pg_temp.field(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.field_service_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.field_services where id=current_setting('field.id')::uuid)||patch)$$;
create function pg_temp.newfield() returns jsonb language sql as $$select public.field_service_command(gen_random_uuid(),'save',jsonb_build_object('order_id','i-order','order_item_id','i-item','service_type','measurement','title','Medição sintética QA','assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'team','[]'::jsonb,'address','{"street":"Rua QA","number":"1","city":"Recife","state":"PE"}'::jsonb,'checklist','[{"id":"check1","label":"Conferência obrigatória","required":true,"done":false}]'::jsonb))$$;
select set_config('field.id',pg_temp.newfield()->>'id',true);
select is((select number from public.field_services where id=current_setting('field.id')::uuid),1::bigint,'tenant-scoped number');
select is(pg_temp.newfield()->>'reused','true','another nonce reuses same active scope');
select lives_ok($$select pg_temp.field('schedule',jsonb_build_object('start',now()+interval '1 day','end',now()+interval '1 day 2 hours'))$$,'schedule canonical service');
select lives_ok($$select pg_temp.field('transition','{"status":"traveling"}')$$,'start travel');
select lives_ok($$select pg_temp.field('transition','{"status":"on_site"}')$$,'arrive');
select lives_ok($$select pg_temp.field('transition','{"status":"running"}')$$,'start execution');
select throws_like($$select pg_temp.field('complete')$$,'%Checklist obrigatório%','required checklist blocks completion');
select lives_ok($$select pg_temp.field('checklist','{"item":"check1","done":true}')$$,'check required item');
select lives_ok($$select pg_temp.field('material_add','{"product_id":"i-material","quantity":3}')$$,'plan additional material');
select set_config('field.material',(select id::text from public.field_service_materials where service_id=current_setting('field.id')::uuid),true);
select lives_ok($$select pg_temp.field('material_take',jsonb_build_object('material_id',current_setting('field.material'),'quantity',3))$$,'take material once');
select is((select current_stock from public.products where id='i-material'),7::numeric,'taking changes canonical stock');
select throws_like($$select pg_temp.field('complete')$$,'%Concilie materiais%','unsettled material blocks completion');
select lives_ok($$select pg_temp.field('material_settle',jsonb_build_object('material_id',current_setting('field.material'),'consumed',2,'returned',1))$$,'consume subset and return leftover');
select is((select current_stock from public.products where id='i-material'),8::numeric,'consumption does not debit again; leftover returns once');
select lives_ok($$select pg_temp.field('complete','{"note":"Concluído apenas em QA"}')$$,'complete execution');
select is((select status from public.orders where id='i-order'),'producao','completion never changes Order status');
select is((select count(*) from public.field_service_completions where service_id=current_setting('field.id')::uuid),1::bigint,'immutable completion snapshot');
select throws_like($$select pg_temp.field('checklist','{"item":"check1","done":false}')$$,'%preserva histórico%','completed execution not silently editable');
select lives_ok($$select pg_temp.field('reopen','{"reason":"Reabertura sintética QA"}')$$,'restricted audited reopening');
select is((select run from public.field_services where id=current_setting('field.id')::uuid),2,'new run preserves previous completion');
select lives_ok($$select pg_temp.field('material_reverse',jsonb_build_object('material_id',current_setting('field.material'),'reason','Encerrar fixture QA'))$$,'inverse canonical material');
select is((select current_stock from public.products where id='i-material'),10::numeric,'stock restored by inverse');
select lives_ok($$select pg_temp.field('cancel','{"reason":"Encerramento da fixture QA"}')$$,'cancel fixture');
select ok((public.field_service_source(current_date,current_date+2,current_setting('field.id')::uuid)->'services')->0 is not null,'authorized historical read');
select set_config('request.jwt.claims','{"sub":"b1190000-0000-4000-8000-000000000002","role":"authenticated"}',true);
grant execute on function pg_temp.field(text,jsonb) to authenticated;
set local role authenticated;
select is((select count(*) from public.field_services),0::bigint,'tenant B cannot read A');
select throws_like($$select public.field_service_command(gen_random_uuid(),'reopen',jsonb_build_object('id',current_setting('field.id'),'updated_at',now(),'reason','Outro tenant'))$$,'%indisponível%','tenant B cannot mutate A');
reset role;
select * from finish();rollback;
